"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[5073],{3331:(e,a,o)=>{o.d(a,{R:()=>d,x:()=>n});var s=o(36672);const i={},r=s.createContext(i);function d(e){const a=s.useContext(r);return s.useMemo((function(){return"function"==typeof e?e(a):{...a,...e}}),[a,e])}function n(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:d(e.components),s.createElement(r.Provider,{value:a},e.children)}},89081:(e,a,o)=>{o.r(a),o.d(a,{assets:()=>t,contentTitle:()=>n,default:()=>u,frontMatter:()=>d,metadata:()=>s,toc:()=>c});const s=JSON.parse('{"id":"2023/04/06","title":"2023-04-06","description":"Lembrando Bob Lee","source":"@site/i18n/pt/docusaurus-plugin-content-docs/current/2023/04/06.md","sourceDirName":"2023/04","slug":"/2023/04/06","permalink":"/pt/2023/04/06","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/pt/docusaurus-plugin-content-docs//current/2023/04/06.md","tags":[],"version":"current","frontMatter":{"localized_date":"6 de abril de 2023","top_news":"Lembrando Bob Lee"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-07","permalink":"/pt/2023/04/07"},"next":{"title":"2023-04-05","permalink":"/pt/2023/04/05"}}');var i=o(23420),r=o(3331);const d={localized_date:"6 de abril de 2023",top_news:"Lembrando Bob Lee"},n="2023-04-06",t={},c=[{value:"Lembrando Bob Lee",id:"lembrando-bob-lee",level:2},{value:"Bob Lee, antigo CTO da Square, morreu depois de ter sido esfaqueado em S\xe3o Francisco",id:"bob-lee-antigo-cto-da-square-morreu-depois-de-ter-sido-esfaqueado-em-s\xe3o-francisco",level:2},{value:"Diga ao iOS permite \xe0s operadoras adicionar redes WiFi que n\xe3o pode parar de aderir",id:"diga-ao-ios-permite-\xe0s-operadoras-adicionar-redes-wifi-que-n\xe3o-pode-parar-de-aderir",level:2},{value:"Fundamentos de Aprendizagem Profunda para a Difus\xe3o Est\xe1vel",id:"fundamentos-de-aprendizagem-profunda-para-a-difus\xe3o-est\xe1vel",level:2},{value:"Inje\xe7\xe3o de CAN: Roubo de carro sem chave",id:"inje\xe7\xe3o-de-can-roubo-de-carro-sem-chave",level:2},{value:"Os engenheiros do Firefox descobrem um bug do Windows Defender que causa uma elevada utiliza\xe7\xe3o de CPU",id:"os-engenheiros-do-firefox-descobrem-um-bug-do-windows-defender-que-causa-uma-elevada-utiliza\xe7\xe3o-de-cpu",level:2},{value:"Segmento Qualquer modelo de qualquer coisa (SAM) pode &quot;recortar&quot; qualquer objecto numa imagem",id:"segmento-qualquer-modelo-de-qualquer-coisa-sam-pode-recortar-qualquer-objecto-numa-imagem",level:2},{value:"O papel branco Bitcoin est\xe1 escondido em cada c\xf3pia de macOS",id:"o-papel-branco-bitcoin-est\xe1-escondido-em-cada-c\xf3pia-de-macos",level:2},{value:"Antigo CTO quadrado Bob Lee Apunhalado at\xe9 \xe0 Morte no Centro de S\xe3o Francisco",id:"antigo-cto-quadrado-bob-lee-apunhalado-at\xe9-\xe0-morte-no-centro-de-s\xe3o-francisco",level:2},{value:"O caso da proibi\xe7\xe3o de crian\xe7as das redes sociais",id:"o-caso-da-proibi\xe7\xe3o-de-crian\xe7as-das-redes-sociais",level:2},{value:"O Dang vai ter 65,535 pontos de karma em breve",id:"o-dang-vai-ter-65535-pontos-de-karma-em-breve",level:2},{value:"Redes Neuronais: Zero a Her\xf3i",id:"redes-neuronais-zero-a-her\xf3i",level:2},{value:"Um truque para alcan\xe7ar o fluxo: Deixe o seu trabalho quebrado",id:"um-truque-para-alcan\xe7ar-o-fluxo-deixe-o-seu-trabalho-quebrado",level:2},{value:"A RAM \xe9 limpa antes de ser utilizada noutro contentor LXC?",id:"a-ram-\xe9-limpa-antes-de-ser-utilizada-noutro-contentor-lxc",level:2},{value:"Perspectiva: WebAssembly-Powered BI de fonte aberta",id:"perspectiva-webassembly-powered-bi-de-fonte-aberta",level:2},{value:"Mundo Grid",id:"mundo-grid",level:2},{value:"Tokenizer OpenAI",id:"tokenizer-openai",level:2},{value:"Tabloid - A Linguagem de Programa\xe7\xe3o Clickbait Headline",id:"tabloid---a-linguagem-de-programa\xe7\xe3o-clickbait-headline",level:2},{value:"GPT4 que simula um servidor FTP em ftp.disney.com",id:"gpt4-que-simula-um-servidor-ftp-em-ftpdisneycom",level:2},{value:"Usando o mmap para tornar a carga LLaMA mais r\xe1pida",id:"usando-o-mmap-para-tornar-a-carga-llama-mais-r\xe1pida",level:2}];function m(e){const a={a:"a",h1:"h1",h2:"h2",header:"header",p:"p",...(0,r.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(a.header,{children:(0,i.jsx)(a.h1,{id:"2023-04-06",children:"2023-04-06"})}),"\n",(0,i.jsx)(a.h2,{id:"lembrando-bob-lee",children:"Lembrando Bob Lee"}),"\n",(0,i.jsx)(a.p,{children:"A comunidade tecnol\xf3gica est\xe1 de luto pela perda de Bob Lee, uma figura bem conhecida na ind\xfastria. Lee foi um defensor de Java, tendo trabalhado no Google e Square, e era conhecido pelo seu trabalho no quadro da injec\xe7\xe3o de depend\xeancia de Guice. Foi tamb\xe9m o co-fundador da Android Alliance, uma iniciativa que visava promover a inova\xe7\xe3o no ecossistema Android. As contribui\xe7\xf5es de Lee para o mundo da tecnologia foram amplamente reconhecidas, e os seus colegas e pares sentir\xe3o grande falta dele. Muitos partilharam as suas condol\xeancias sobre as redes sociais, recordando Lee como um mentor e amigo que sempre arranjou tempo para os outros. Descanse em paz, Bob Lee."}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35457341",children:"Discussion Service"}),".\nBob Lee, o co-autor das bibliotecas Guice e Java, conhecido pelas suas capacidades t\xe9cnicas, gentileza e humildade, faleceu. A sua morte deixou a comunidade t\xe9cnica em luto e levou muitas pessoas a partilhar as suas mem\xf3rias e anedotas a seu respeito. O legado de inova\xe7\xe3o e paix\xe3o de Lee inspirou muitos, e as suas contribui\xe7\xf5es para a ind\xfastria far\xe3o falta. Enquanto alguns coment\xe1rios digeriram, a maioria partilhou pensamentos e experi\xeancias positivas sobre Bob."]}),"\n",(0,i.jsx)(a.h2,{id:"bob-lee-antigo-cto-da-square-morreu-depois-de-ter-sido-esfaqueado-em-s\xe3o-francisco",children:"Bob Lee, antigo CTO da Square, morreu depois de ter sido esfaqueado em S\xe3o Francisco"}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"https://www.sfgate.com/bayarea/article/mill-valley-man-killed-sf-stabbing-17878809.php",children:"Original"}),".\nBob Lee, o criador da Cash App como Chief Technology Officer na Square, foi identificado como o homem que foi morto em S\xe3o Francisco devido a um incidente de esfaqueamento; o evento chocou o mundo tecnol\xf3gico, com as pessoas a reagirem \xe0s s\xfabitas not\xedcias. A pol\xedcia n\xe3o efectuou quaisquer deten\xe7\xf5es ou divulgou quaisquer informa\xe7\xf5es relativas a poss\xedveis suspeitos. Lee tinha 43 anos de idade, foi o fundador da Cash App, e tinha estado a trabalhar como Chefe de Produto na MobileCoin na altura da sua morte."]}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35448899",children:"Discussion Service"}),".\nO antigo CTO da Square, Bob Lee, morto em S\xe3o Francisco, desencadeia uma discuss\xe3o sobre crime e governa\xe7\xe3o. Os coment\xe1rios abrangem a disparidade de riqueza, os sem-abrigo, a gentrifica\xe7\xe3o, e potenciais solu\xe7\xf5es. A discuss\xe3o suscita desafios sobre sistemas pol\xedticos e estat\xedsticas de crime n\xe3o fi\xe1veis nas cidades dos EUA. Os utilizadores discutem causas potenciais do crime, incluindo migra\xe7\xe3o em massa, desigualdade de riqueza, sistemas de justi\xe7a impactados e falta de resposta da pol\xedcia. A compara\xe7\xe3o do crime entre diferentes pa\xedses ou culturas n\xe3o \xe9 \xfatil. A quest\xe3o do crime \xe9 complexa e n\xe3o \xe9 o resultado de qualquer factor isolado."]}),"\n",(0,i.jsx)(a.h2,{id:"diga-ao-ios-permite-\xe0s-operadoras-adicionar-redes-wifi-que-n\xe3o-pode-parar-de-aderir",children:"Diga ao iOS permite \xe0s operadoras adicionar redes WiFi que n\xe3o pode parar de aderir"}),"\n",(0,i.jsx)(a.p,{children:'O sistema operativo iOS permite aos portadores acrescentar redes WiFi que os utilizadores n\xe3o podem optar por n\xe3o aderir. Esta caracter\xedstica est\xe1 a causar preocupa\xe7\xe3o entre os utilizadores de iPhone que t\xeam planos de dados limitados ou preocupa\xe7\xf5es de privacidade. A funcionalidade destina-se a ajudar as operadoras a lan\xe7ar hotspots WiFi, mas tamb\xe9m lhes permite adicionar redes WiFi p\xfablicas a que os utilizadores se ligam sem saberem, potencialmente recolhendo dados sens\xedveis. Os utilizadores t\xeam op\xe7\xf5es limitadas para desactivar a funcionalidade, incluindo desactivar completamente o WiFi ou optar por "Esquecer esta rede" sempre que a encontrarem. Alguns utilizadores pedem \xe0 Apple que acrescente mais controlo sobre esta funcionalidade, enquanto outros sugerem a utiliza\xe7\xe3o de uma VPN para proteger os seus dados.'}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35447486",children:"Discussion Service"}),".\nO iOS 16.4 permite \xe0s operadoras adicionar redes geridas a dispositivos, reduzir os custos celulares, e impedir a desactiva\xe7\xe3o da auto-inser\xe7\xe3o, sem nenhuma forma actual de remover estas redes, a n\xe3o ser reiniciando as configura\xe7\xf5es da rede. Os utilizadores reportam que a T-Mobile rouba dados e que as redes Wingman em voo n\xe3o se desligam, e que os transportadores ditam liga\xe7\xf5es WiFi sem recurso ao utilizador. Segue-se um debate sobre como obter um controlo completo do dispositivo, com alguns utilizadores a recomendarem GrapheneOS para actualiza\xe7\xf5es de seguran\xe7a. Os hotspots WiFi das transportadoras s\xe3o criticados por interromperem as liga\xe7\xf5es a dispositivos locais, e alguns acham a funcionalidade \xfatil em \xe1reas com muita gente."]}),"\n",(0,i.jsx)(a.h2,{id:"fundamentos-de-aprendizagem-profunda-para-a-difus\xe3o-est\xe1vel",children:"Fundamentos de Aprendizagem Profunda para a Difus\xe3o Est\xe1vel"}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"https://course.fast.ai/Lessons/part2.html",children:"Original"}),'.\n"Practical Deep Learning for Coders - Part 2" \xe9 um curso que consiste em mais de 30 horas de conte\xfado v\xeddeo que inclui a cobertura do algoritmo de Difus\xe3o Est\xe1vel a partir do zero, trabalhando em estreita colabora\xe7\xe3o com especialistas do Stable.ai e Hugging Face. O curso fornece uma cobertura rigorosa das t\xe9cnicas mais recentes e vai al\xe9m mesmo do que o Stable Diffusion inclui, tornando-o um grande objectivo de aprendizagem por muitas raz\xf5es, no entanto, para tirar o m\xe1ximo proveito deste curso, dever\xe1 ser um praticante de aprendizagem profunda razoavelmente confiante. Ao longo do curso, iremos explorar m\xe9todos de difus\xe3o, implementar os nossos pr\xf3prios modelos a partir do zero, dominar conceitos de Python, e PyTorch para implementar os nossos modelos. Cobriremos fundamentos de difus\xe3o, optimizadores de aprendizagem profunda, conceitos Python, fundamentos b\xe1sicos, gera\xe7\xe3o de n\xfameros pseudo-aleat\xf3rios, arquitecturas de redes neurais, arquitecturas generativas, transformadores, e treino misto de precis\xe3o.']}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35449831",children:"Discussion Service"}),".\nO 'Fundamentos de Aprendizagem Profunda para a Difus\xe3o Est\xe1vel' explora a modela\xe7\xe3o generativa moderna enquanto alguns recomendam que se concentre no marketing. O curso Fast.ai de aprendizagem profunda cria um quadro de programa\xe7\xe3o a partir do zero e \xe9 recomendado para qualquer pessoa interessada nele. H\xe1 um debate em torno dos perigos potenciais da IA avan\xe7ada e da import\xe2ncia da regulamenta\xe7\xe3o e das considera\xe7\xf5es \xe9ticas. Os comentadores sugerem a proibi\xe7\xe3o da produ\xe7\xe3o de IA, mas n\xe3o \xe9 uma solu\xe7\xe3o a longo prazo, a menos que todos os pa\xedses o fa\xe7am. O curso de FastAI n\xe3o tem declara\xe7\xf5es pol\xedtica ou religiosamente tendenciosas, e o seu conte\xfado \xe9 considerado de primeira linha. O curso \xe9 acess\xedvel a qualquer pessoa com conhecimentos b\xe1sicos de matem\xe1tica do ensino secund\xe1rio e cobre conceitos avan\xe7ados."]}),"\n",(0,i.jsx)(a.h2,{id:"inje\xe7\xe3o-de-can-roubo-de-carro-sem-chave",children:"Inje\xe7\xe3o de CAN: Roubo de carro sem chave"}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"https://kentindell.github.io/2023/04/03/can-injection/",children:"Original"}),".\nOs ladr\xf5es de carros est\xe3o a utilizar uma nova t\xe9cnica chamada Injec\xe7\xe3o CAN para contornar sistemas de chave inteligente em carros modernos, explorando vulnerabilidades no protocolo de comunica\xe7\xe3o de autocarros CAN. Sistemas sofisticados de seguran\xe7a autom\xf3vel, incluindo imobilizadores de motor, tornaram-se vulner\xe1veis. Os ladr\xf5es usam um dispositivo chamado CAN Injector para roubar carros sem a chave, injectando mensagens falsas no sistema de comunica\xe7\xe3o interna do carro. O dispositivo custa $10 e cont\xe9m um chip PIC18F, firmware pr\xe9-programado, um transceptor, e um circuito extra. Uma repara\xe7\xe3o r\xe1pida ou mensagens criptogr\xe1ficas pode derrotar o Injector CAN. Ian Haken descreve v\xe1rias formas como os fabricantes de autom\xf3veis poderiam ajudar a proteger os carros, mas a explora\xe7\xe3o criminosa da t\xe9cnica \xe9 generalizada. Trata-se de uma quest\xe3o de \xe2mbito industrial que requer uma actualiza\xe7\xe3o do software da ECU para derrotar os ladr\xf5es."]}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35452963",children:"Discussion Service"}),".\nUma t\xe9cnica de roubo de carros sem chave conhecida como CAN Injection foi destacada no Hacker News. Os consumidores devem desconfiar de encriptar ou assinar o CAN Bus, pois pode limitar as ferramentas de diagn\xf3stico de terceiros, aumentando os custos de repara\xe7\xe3o. O CAN bus controla m\xfaltiplas fun\xe7\xf5es do ve\xedculo, e os fabricantes de ve\xedculos optimizam implacavelmente os custos. Os fabricantes de autom\xf3veis t\xeam requisitos legais para se separarem dos concession\xe1rios, mas alguns coment\xe1rios criticam a sua ader\xeancia ao esp\xedrito da lei. As marcas de autom\xf3veis Premium utilizam v\xe1rias medidas de seguran\xe7a para impedir a pirataria de autom\xf3veis, incluindo imobilizadores com protocolos criptogr\xe1ficos adequados para autenticar mensagens de arranque e quadros CAN/FlexRay/Ethernet assinados para impedir a falsifica\xe7\xe3o de mensagens. Os carros baratos s\xe3o visados por serem f\xe1ceis de roubar, enquanto que os carros caros s\xe3o alvo de roubo violento. A explora\xe7\xe3o descrita no artigo poderia ser aplicada a quase todos os ve\xedculos n\xe3o ligados, fabricados na \xfaltima d\xe9cada. A utiliza\xe7\xe3o de CAN bus em sistemas cr\xedticos como a avia\xe7\xe3o e o autom\xf3vel deve-se \xe0 sua simplicidade de cablagem e \xe0 sua rela\xe7\xe3o custo-efic\xe1cia."]}),"\n",(0,i.jsx)(a.h2,{id:"os-engenheiros-do-firefox-descobrem-um-bug-do-windows-defender-que-causa-uma-elevada-utiliza\xe7\xe3o-de-cpu",children:"Os engenheiros do Firefox descobrem um bug do Windows Defender que causa uma elevada utiliza\xe7\xe3o de CPU"}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"https://bugzilla.mozilla.org/show_bug.cgi?id=1441918#c82",children:"Original"}),".\nN/A (Este texto n\xe3o est\xe1 relacionado com o tema)."]}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35458746",children:"Discussion Service"}),".\nOs engenheiros do Firefox encontraram um bug do Windows Defender que causava a utiliza\xe7\xe3o de CPU no navegador do Mozilla. A Microsoft est\xe1 a lan\xe7ar um patch para corrigir isto. Outros produtos AV poderiam tamb\xe9m causar problemas de utiliza\xe7\xe3o de CPU. O Firefox faz mais chamadas ao sistema do que o Chrome por raz\xf5es de seguran\xe7a. Uma compara\xe7\xe3o mostra que o Firefox tem um desempenho mais r\xe1pido que o Chrome em alguns testes. Especialistas discutem as limita\xe7\xf5es do Defender, sugerem o sandboxing e o hardware MFA. Os utilizadores debatem a efic\xe1cia do Defender versus software AV de terceiros. Alguns utilizadores relatam problemas com o Defender, causando lentid\xe3o no acesso ao sistema de ficheiros."]}),"\n",(0,i.jsx)(a.h2,{id:"segmento-qualquer-modelo-de-qualquer-coisa-sam-pode-recortar-qualquer-objecto-numa-imagem",children:'Segmento Qualquer modelo de qualquer coisa (SAM) pode "recortar" qualquer objecto numa imagem'}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"https://segment-anything.com/",children:"Original"}),".\nO Segment Anything Model (SAM) desenvolvido pela Meta AI pode isolar qualquer objecto numa imagem com alta precis\xe3o. Pode identificar e segmentar com sucesso objectos, mesmo quando estes est\xe3o parcialmente vis\xedveis ou oclu\xeddos. O SAM melhora os modelos previamente desenvolvidos que se baseiam em pistas de localiza\xe7\xe3o ou objectos salientes. Em vez de utilizar estas dicas, a SAM aplica a meta-aprendizagem, aproveitando a aprendizagem de um modelo existente, para ser capaz de detectar conjuntos de dados pequenos e tendenciosos ou objectos n\xe3o vis\xedveis. A SAM pode ser utilizada para aplica\xe7\xf5es pr\xe1ticas, como a edi\xe7\xe3o de imagens, bem como a investiga\xe7\xe3o no campo da vis\xe3o por computador."]}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35455566",children:"Discussion Service"}),'.\nO SAM da Meta AI permite a gera\xe7\xe3o de m\xe1scaras em tempo real para "recortar" qualquer objecto a partir de uma imagem. O licenciamento do modelo e as suas impressionantes capacidades de infer\xeancia podem torn\xe1-lo popular entre os especialistas em tecnologia. As quest\xf5es incluem velocidade mais lenta com o modelo RTX 2080ti 11GB e precis\xe3o limitada com objectos transparentes. Alguns v\xeaem a estrat\xe9gia de lan\xe7amento da Meta AI como parte de um impulso \xe0 adop\xe7\xe3o de AR. Os utilizadores elogiam a redu\xe7\xe3o de custos de anota\xe7\xe3o de dados da SAM, mas criticam a sua velocidade e comparam-na com o iOS. O desenvolvimento pode tamb\xe9m ter uma potencial aplica\xe7\xe3o de c\xe2mara de seguran\xe7a e integra\xe7\xe3o com AdobeAI.']}),"\n",(0,i.jsx)(a.h2,{id:"o-papel-branco-bitcoin-est\xe1-escondido-em-cada-c\xf3pia-de-macos",children:"O papel branco Bitcoin est\xe1 escondido em cada c\xf3pia de macOS"}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"https://waxy.org/2023/04/the-bitcoin-whitepaper-is-hidden-in-every-modern-copy-of-macos/",children:"Original"}),'.\nUma c\xf3pia PDF do livro branco Bitcoin da Satoshi Nakamoto foi descoberta em todas as c\xf3pias modernas de macOS desde Mojave em 2018, e pode ser acedida atrav\xe9s de um documento de amostra no utilit\xe1rio Image Capture. O whitepaper \xe9 utilizado como um documento de amostra para um dispositivo chamado "Virtual Scanner II", que ou est\xe1 escondido ou n\xe3o est\xe1 instalado para todos por defeito. Embora a raz\xe3o da sua inclus\xe3o ainda n\xe3o seja clara, pode ter sido um PDF de v\xe1rias p\xe1ginas conveniente e leve para fins de teste. H\xe1 muito pouca informa\xe7\xe3o dispon\xedvel online sobre o Virtual Scanner II ou a inclus\xe3o do whitepaper no MacOS.']}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35461011",children:"Discussion Service"}),".\nO papel branco Bitcoin est\xe1 escondido em todas as c\xf3pias macOS desde 2019; especula\xe7\xf5es rodeiam o porqu\xea da sua inclus\xe3o, e os utilizadores advertem contra a minera\xe7\xe3o em iPhones. A soma do hash corresponde \xe0 vers\xe3o original, mas as teorias variam sobre o porqu\xea da sua inclus\xe3o. Surgem queixas sobre o endosso de um esquema Ponzi, mas os utilizadores esclarecem que est\xe1 escondido. A Apple pode t\xea-lo inclu\xeddo por conveni\xeancia, mas o post desencadeia o di\xe1logo sobre o impacto do Bitcoin. Os utilizadores comentam sobre a imagem utilizada num artigo, tamanho de ficheiro PDF, e tecnologia perdendo a sua divers\xe3o art\xedstica."]}),"\n",(0,i.jsx)(a.h2,{id:"antigo-cto-quadrado-bob-lee-apunhalado-at\xe9-\xe0-morte-no-centro-de-s\xe3o-francisco",children:"Antigo CTO quadrado Bob Lee Apunhalado at\xe9 \xe0 Morte no Centro de S\xe3o Francisco"}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"https://sfstandard.com/criminal-justice/san-francisco-stabbing-victim-bob-lee-former-cto-square-mobilecoin/",children:"Original"}),".\nO antigo CTO quadrado Bob Lee foi esfaqueado at\xe9 \xe0 morte no centro de S\xe3o Francisco, de acordo com The Standard. Lee era o Chefe de Produto da MobileCoin, uma empresa de criptografia em S\xe3o Francisco, e um amado membro das comunidades de desenvolvimento de software e tecnologia da Bay Area. A SFPD n\xe3o divulgou quaisquer detalhes adicionais ou a identidade da v\xedtima, e est\xe1 a solicitar testemunhas oculares e filmagens de v\xeddeo para a sua investiga\xe7\xe3o. S\xe3o Francisco sofreu 12 homic\xeddios desde 2 de Abril, mais dois do que no mesmo per\xedodo do ano passado. A Norma cobre hist\xf3rias importantes, incluindo quest\xf5es de justi\xe7a criminal em S\xe3o Francisco, e fornece boletins informativos e uma vis\xe3o abrangente da pol\xedtica e cultura de S\xe3o Francisco."]}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35452426",children:"Discussion Service"}),".\nEx-CTO quadrado Bob Lee apunhalado at\xe9 \xe0 morte em S\xe3o Francisco; os coment\xe1rios referem-se a novos detalhes."]}),"\n",(0,i.jsx)(a.h2,{id:"o-caso-da-proibi\xe7\xe3o-de-crian\xe7as-das-redes-sociais",children:"O caso da proibi\xe7\xe3o de crian\xe7as das redes sociais"}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"https://www.newyorker.com/news/our-columnists/the-case-for-banning-children-from-social-media",children:"Original"}),".\nO debate sobre a proibi\xe7\xe3o de crian\xe7as dos meios de comunica\xe7\xe3o social est\xe1 em curso devido a preocupa\xe7\xf5es sobre depend\xeancia e negativismo. Alguns projectos de lei foram aprovados para restringir o acesso de menores a s\xedtios de redes sociais e remover caracter\xedsticas viciantes, mas isto levanta implica\xe7\xf5es civis-libertistas e limita o acesso a not\xedcias e perspectivas diferentes, colocando a quest\xe3o de como as redes sociais devem ser tratadas. Embora os tribunais tenham derrubado as protec\xe7\xf5es em linha para a seguran\xe7a das crian\xe7as, a cria\xe7\xe3o de mensagens anti-adi\xe7\xe3o e restri\xe7\xf5es legais apresentam potenciais conflitos com os direitos da Primeira Emenda, e os pais podem ter de recorrer \xe0 remo\xe7\xe3o f\xedsica dos ecr\xe3s. A protec\xe7\xe3o das crian\xe7as em linha \xe9 um debate pol\xedtico e cultural, deixando pouca confian\xe7a na capacidade do governo para regular as empresas de meios de comunica\xe7\xe3o social."]}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35447588",children:"Discussion Service"}),".\nUm artigo defende a proibi\xe7\xe3o dos meios de comunica\xe7\xe3o social para menores de 18 anos devido a uma potencial toxicodepend\xeancia; a regulamenta\xe7\xe3o de tal conte\xfado coloca dificuldades. Um debate sobre a defini\xe7\xe3o e influ\xeancia de an\xfancios dirigidos a crian\xe7as suscita preocupa\xe7\xf5es sobre a regulamenta\xe7\xe3o da publicidade. Os efeitos nocivos dos meios de comunica\xe7\xe3o social na sa\xfade mental e no desenvolvimento pessoal s\xe3o levantados, suscitando sugest\xf5es para proibir os meios de comunica\xe7\xe3o social empresariais e os alimentos algor\xedtmicos. Uma proibi\xe7\xe3o geral das redes sociais n\xe3o \xe9 vista como a solu\xe7\xe3o; s\xe3o necess\xe1rias abordagens diferenciadas. Os utilizadores de Discussion Service discutem formas eficazes de limitar o tempo de rastreio e combater os efeitos negativos. O debate centra-se na procura de um equil\xedbrio entre a liberdade individual e a responsabilidade social. As preocupa\xe7\xf5es sobre o controlo das redes sociais e a liberta\xe7\xe3o de dopamina no c\xe9rebro suscitam discuss\xf5es sobre os algoritmos de proibi\xe7\xe3o das redes sociais. A viabilidade e a potencial intrus\xe3o na privacidade s\xe3o destacadas como preocupa\xe7\xf5es sobre a verifica\xe7\xe3o obrigat\xf3ria da identifica\xe7\xe3o das contas dos meios de comunica\xe7\xe3o social. N\xe3o \xe9 discutida qualquer nova tecnologia ou grande divulga\xe7\xe3o."]}),"\n",(0,i.jsx)(a.h2,{id:"o-dang-vai-ter-65535-pontos-de-karma-em-breve",children:"O Dang vai ter 65,535 pontos de karma em breve"}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"https://news.ycombinator.com/user?id=dang",children:"Original"}),".\nEspera-se que o utilizador Discussion Service 'dang' atinja em breve 65.535 pontos de karma, que \xe9 o limite m\xe1ximo devido \xe0 utiliza\xe7\xe3o pelo sistema de um inteiro de 16 bits assinado."]}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35460732",children:"Discussion Service"}),".\nDaniel Gackle, AKA Dang, prestes a atingir 65,535 karma. Sec\xe7\xe3o de coment\xe1rios repleta de elogios ao trabalho de Dang. Os utilizadores especulam se o karma vai rolar e discutem a mudan\xe7a para 32-bit int. O estilo de modera\xe7\xe3o e o envolvimento do Y Combinator s\xe3o questionados. Alcan\xe7ar um karma elevado visto como uma forma de mostrar apre\xe7o pelo trabalho de Dang. Atingir marcos de carma mais elevados permite capacidades adicionais no Discussion Service, tais como o upvoting/downvoting."]}),"\n",(0,i.jsx)(a.h2,{id:"redes-neuronais-zero-a-her\xf3i",children:"Redes Neuronais: Zero a Her\xf3i"}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"https://karpathy.ai/zero-to-hero.html",children:"Original"}),'.\nO curso "Redes Neuronais: Zero para Her\xf3i" de Andrej Karpathy ensina a construir redes neuronais a partir do zero em c\xf3digo. O curso come\xe7a com as bases da retropropaga\xe7\xe3o e avan\xe7a para redes neurais profundas modernas como a GPT. O curso concentra-se em modelos lingu\xedsticos, uma vez que s\xe3o um excelente local para aprender a aprender profundamente. Os pr\xe9-requisitos incluem programa\xe7\xe3o s\xf3lida e matem\xe1tica a n\xedvel de introdu\xe7\xe3o. O curso inclui a constru\xe7\xe3o de microgradua\xe7\xe3o, makemore, um MLP, e mergulho em alguns dos internos dos MLPs. Tornar-se um Backprop Ninja e construir a WaveNet s\xe3o tamb\xe9m abrangidos. O curso culmina com a constru\xe7\xe3o de GPT. Os v\xeddeos fornecem uma explica\xe7\xe3o passo a passo e concentram-se na compet\xeancia e intui\xe7\xe3o de constru\xe7\xe3o em torno de como as redes neurais s\xe3o optimizadas. O curso recomenda aos telespectadores que vejam os v\xeddeos anteriores para se sentirem confort\xe1veis com a estrutura de modelagem da linguagem autoregressiva e os princ\xedpios b\xe1sicos de tensores e PyTorch nn.']}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35459031",children:"Discussion Service"}),".\nAndrej Karpathy's 'Neural Networks': Curso \"Zero para Her\xf3i\" ganha mais de 300 pontos no Hacker News em 6 horas. Os utilizadores de Discussion Service elogiam o seu estilo de ensino e recomendam a sua codifica\xe7\xe3o depois de verem os v\xeddeos. O seu curso ML liderado por colegas recebe um feedback positivo apesar de n\xe3o o mencionar. A sintaxe espec\xedfica de Python nos v\xeddeos pode desafiar alguns utilizadores. Uma discuss\xe3o avalia a \xeanfase do curso na regress\xe3o log\xedstica e perceptron. Os participantes acharam o curso f\xe1cil de compreender e recomendam outros cursos para principiantes. Alguns utilizadores questionam os conhecimentos m\xednimos dos programadores web, e um utilizador tem uma teoria sobre a liga\xe7\xe3o entre o ML e a \xe1lgebra Hopf."]}),"\n",(0,i.jsx)(a.h2,{id:"um-truque-para-alcan\xe7ar-o-fluxo-deixe-o-seu-trabalho-quebrado",children:"Um truque para alcan\xe7ar o fluxo: Deixe o seu trabalho quebrado"}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"https://census.dev/blog/an-on-ramp-to-flow",children:"Original"}),'.\nO artigo discute a dificuldade de entrar num estado de "fluxo" nas tarefas de engenharia e fornece um truque para reentrar no fluxo. O autor sugere deixar o seu trabalho num estado obviamente quebrado mas f\xe1cil de reparar antes de se afastar. Isto permite um ponto de partida claro quando se regressa ao trabalho, criando \xedmpeto e confian\xe7a. O artigo reconhece que esta abordagem pode n\xe3o ser universal ou aplic\xe1vel em cen\xe1rios de equipa, mas convida ao feedback para outros truques. H\xe1 tamb\xe9m uma breve men\xe7\xe3o \xe0 Engenharia Censit\xe1ria e \xe0s oportunidades de emprego.']}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35456059",children:"Discussion Service"}),'.\nOs utilizadores de Discussion Service partilham dicas para alcan\xe7ar o estado de fluxo deixando o trabalho inacabado, incluindo o m\xe9todo "park facing downhill". Um director de engenharia implementou deixar o trabalho at\xe9 \xe0s 18 horas para evitar o esgotamento, mas terminou-o devido ao presentee\xedsmo. Os utilizadores discutem os benef\xedcios e os riscos de regras de tempo estritas e de mudan\xe7a de cultura de trabalho. Alguns partilham dicas de produtividade, tais como escrever os pr\xf3ximos passos e praticar o TDD. Deixar o c\xf3digo num estado "quebrado" pode ajudar a retom\xe1-lo mais tarde, mas tem resultados mistos.']}),"\n",(0,i.jsx)(a.h2,{id:"a-ram-\xe9-limpa-antes-de-ser-utilizada-noutro-contentor-lxc",children:"A RAM \xe9 limpa antes de ser utilizada noutro contentor LXC?"}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"https://security.stackexchange.com/questions/269507/is-ram-wiped-before-use-in-another-lxc-container",children:"Original"}),".\nUm post no Information Security Stack Exchange pergunta se a RAM \xe9 limpa antes de ser utilizada noutro contentor LXC, conduzindo a uma discuss\xe3o sobre a sobreprovis\xe3o da RAM no LXC, com um utilizador a comentar que a mem\xf3ria atribu\xedda a um processo anterior num contentor \xe9 limpa. Um post no Hacker News aprofunda, discutindo bibliotecas partilhadas e protec\xe7\xf5es do espa\xe7o de nomes de utilizadores, e uma resposta esclarece que as p\xe1ginas s\xe3o apagadas antes da atribui\xe7\xe3o, o sobreprovisionamento n\xe3o causa partilha, e a mem\xf3ria LXC \xe9 atribu\xedda a processos atrav\xe9s de espa\xe7os de nomes, mas os processos s\xe3o separados dos recursos do anfitri\xe3o. Finalmente, nota-se que a gest\xe3o de mem\xf3ria baseada em glibc n\xe3o envolve limpeza e as p\xe1ginas livres podem conter dados."]}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35451863",children:"Discussion Service"}),".\nOs utilizadores no Hacker News discutiram a efic\xe1cia e necessidade da zeragem autom\xe1tica da mem\xf3ria no Linux, com algumas sugest\xf5es de m\xe9todos alternativos para limpar a mem\xf3ria n\xe3o utilizada. Um utilizador salientou que o problema reside na concep\xe7\xe3o do garfo() do sistema UNIX, e muitos softwares de mem\xf3ria intensiva ainda se debatem com quest\xf5es OOM. Outros coment\xe1rios discutem as diferen\xe7as entre a aloca\xe7\xe3o de mem\xf3ria com e sem excesso de compromisso no Linux e a import\xe2ncia de estabelecer limites. O artigo fornece perspectivas matizadas sobre a aloca\xe7\xe3o de mem\xf3ria no Linux e est\xe1 orientado para especialistas na mat\xe9ria."]}),"\n",(0,i.jsx)(a.h2,{id:"perspectiva-webassembly-powered-bi-de-fonte-aberta",children:"Perspectiva: WebAssembly-Powered BI de fonte aberta"}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"https://perspective.finos.org/",children:"Original"}),".\nPerspective \xe9 um componente interactivo de an\xe1lise e visualiza\xe7\xe3o de dados, concebido para streaming e grandes conjuntos de dados com relat\xf3rios configur\xe1veis, dashboards e cadernos. Apresenta um motor de consulta de streaming eficiente de mem\xf3ria em C++ e Python e uma IU embalada como um Elemento Personalizado alimentado por WebAssembly ou WebSocket. A IU inclui dashboards interactivos que podem ser integrados em qualquer estrutura de aplica\xe7\xe3o Web. Perspective.js depende de WebAssembly e Apache Arrow para um desempenho semelhante ao do ambiente de trabalho no navegador. PerspectivePython implementa a Perspective API directamente em Python para investiga\xe7\xe3o ou produ\xe7\xe3o. Existem widgets virtualizados e escal\xe1veis, e o projecto est\xe1 dispon\xedvel no GitHub com guias de utilizador e programador."]}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35455850",children:"Discussion Service"}),".\nFerramenta de BI de c\xf3digo-fonte aberto, alimentada por WebAssembly Perspective elogiada por uma funcionalidade poderosa, apesar dos problemas de desempenho: as solu\xe7\xf5es sugeridas incluem a utiliza\xe7\xe3o de uma op\xe7\xe3o mais leve. Os fabricantes da Perspective trabalham para melhorar o desempenho e a compatibilidade m\xf3vel. Algumas preocupa\xe7\xf5es levantadas sobre o suporte e acessibilidade do Firefox/n\xe3o teclado de design amig\xe1vel. Limita\xe7\xf5es do Sciter discutidas, bibliotecas Tauri vistas como potencialmente \xfateis. Melhorias de desempenho necess\xe1rias para o projecto Perspective."]}),"\n",(0,i.jsx)(a.h2,{id:"mundo-grid",children:"Mundo Grid"}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"https://alex.miller.garden/grid-world/",children:"Original"}),'.\nO "Grid World" de Alexander Miller explora o papel das grelhas na sua vida desde a inf\xe2ncia at\xe9 \xe0 idade adulta, incluindo o seu impacto na tecnologia, arte, e navega\xe7\xe3o. O artigo aborda o poder que as grelhas t\xeam no mapeamento e controlo do espa\xe7o, como se v\xea em jogos como o Batalha Naval e o Xadrez. A grelha torna-se um n\xfacleo central que liga as experi\xeancias pessoais de Miller, mostrando como ela se torna parte das nossas vidas. Miller criou a grelha para a The HTML Review em 2023.']}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35455770",children:"Discussion Service"}),".\nOs utilizadores de Discussion Service s\xe3o fascinados pelo excepcional dom\xednio e destreza do Grid World no design & desenvolvimento da web e o seu impacto na percep\xe7\xe3o. O artigo explora a subestrutura da grelha para as nossas mem\xf3rias e para o mundo, com acompanhamento de imagens pixel art\xedsticas. Os coment\xe1rios notam a liga\xe7\xe3o \xe0 neuroci\xeancia com as c\xe9lulas da grelha ao mesmo tempo que levantam cr\xedticas sobre a racionaliza\xe7\xe3o e a manta da grelha sobre a natureza. Um utilizador tem dificuldade em aperfei\xe7oar os aspectos de design visual do seu projecto pessoal. Os utilizadores discutem os padr\xf5es de grelha das Rainhas e a hist\xf3ria por detr\xe1s dos padr\xf5es da grelha. Um utilizador da Discussion Service compartilha as suas ideias sobre a conformidade da grelha de rua de NYC. Uma decora\xe7\xe3o em forma de mesa gera salas de confus\xe3o pouco iluminadas enquanto evoluem ao longo do tempo, constru\xeddas com javascript simples sem quaisquer bibliotecas para exerc\xedcio t\xe9cnico divertido."]}),"\n",(0,i.jsx)(a.h2,{id:"tokenizer-openai",children:"Tokenizer OpenAI"}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"https://platform.openai.com/tokenizer",children:"Original"}),".\nO OpenAI API \xe9 uma tecnologia que requer que o JavaScript esteja activado."]}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35453400",children:"Discussion Service"}),".\nO OpenAI lan\xe7ou um novo tokenizer para melhor compreender os modelos GPT. O tokenizer divide o texto em unidades de sub-palavras para um processamento eficiente, mas falta-lhes um significado inerente. Os utilizadores de Discussion Service discutem as limita\xe7\xf5es da ferramenta, tais como o agrupamento baseado em espa\xe7os e tratamentos de capitaliza\xe7\xe3o. As codifica\xe7\xf5es criadas utilizando a codifica\xe7\xe3o por pares de bytes n\xe3o s\xe3o muitas vezes bem adaptadas a l\xednguas subrepresentadas. O OpenAI cobra por ficha devido \xe0 opera\xe7\xe3o baseada na ficha do modelo."]}),"\n",(0,i.jsx)(a.h2,{id:"tabloid---a-linguagem-de-programa\xe7\xe3o-clickbait-headline",children:"Tabloid - A Linguagem de Programa\xe7\xe3o Clickbait Headline"}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"https://tabloid-thesephist.vercel.app/",children:"Original"}),".\nTabloid \xe9 uma nova linguagem de programa\xe7\xe3o criada para gerar manchetes rid\xedculas e dignas de clique, parecidas com as vistas nos tabl\xf3ides. A linguagem usa uma combina\xe7\xe3o de processamento de linguagem natural, aprendizagem de m\xe1quinas, e crowd-sourcing para criar manchetes com padr\xf5es lingu\xedsticos de clickbaity. \xc9 uma linguagem divertida e divertida que n\xe3o serve nenhum objectivo real, mas \xe9 um excelente exemplo de como a programa\xe7\xe3o pode ser \xfatil e divertida. O criador do Tabloid planeia us\xe1-la para criar uma plataforma que permita a qualquer pessoa criar as suas manchetes de clickbait. Os utilizadores de Discussion Service consideram esta ferramenta interessante e uma forma \xfatil de compreender o processamento de linguagem natural."]}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35447580",children:"Discussion Service"}),'.\nUm projecto recente no Hacker News chamado Tabloid - The Clickbait Headline Programming Language. O projecto \xe9 fascinante, escrito por um autor que afirma ter escrito outras l\xednguas que s\xe3o indiscutivelmente mais \xfateis. Um utilizador Discussion Service publicou um programa no Tabloid que leva cinco n\xfameros e devolve o produto dos primeiros tr\xeas n\xfameros mais o produto dos dois \xfaltimos. O autor \xe9 algu\xe9m que enviou muitos projectos interessantes, mesmo usando Oak para construir um monte de infra-estruturas de software pessoal, entre outras coisas. Outro utilizador da Discussion Service comentou que escrever tudo do zero \xe9 mais vi\xe1vel para programadores solit\xe1rios, mas n\xe3o para equipas, onde \xe9 melhor ir com "aborrecido".']}),"\n",(0,i.jsx)(a.h2,{id:"gpt4-que-simula-um-servidor-ftp-em-ftpdisneycom",children:"GPT4 que simula um servidor FTP em ftp.disney.com"}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"https://www.filestash.app/2023/04/01/chat-gpt-acting-as-a-ftp-server/",children:"Original"}),".\nO Chat GPT-4 \xe9 h\xe1bil na simula\xe7\xe3o de um servidor FTP para a Disney, usando a ferramenta de base ftp cli e os pr\xf3ximos prompts para executar comandos como um utilizador real o faria. O servidor simulado inclui conte\xfado exclusivo da Disney em pastas como filmes, bandas sonoras e wallpapers, e o GPT-4 prova ser capaz de navegar em sistemas de ficheiros locais e remotos. A nova tecnologia funciona bem, excedendo as expectativas e demonstrando a sua capacidade de criar conte\xfados convincentes para os entusiastas da Disney. O artigo sugere utiliza\xe7\xf5es futuras para o GPT-4 em plugins de int\xe9rpretes de c\xf3digo que permitem o acesso a servidores inventados a partir de clientes FTP."]}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35450315",children:"Discussion Service"}),".\nUm artigo no Hacker News discute o GPT4 que simula um servidor FTP em ftp.disney.com. Os utilizadores debatem se isto pode ou n\xe3o ser considerado 'alucinante', apesar do seu potencial para a IA simular ou 'alucinar'. A precis\xe3o das respostas geradas pela IA e a percep\xe7\xe3o destes resultados como \"alucina\xe7\xf5es\" s\xe3o tamb\xe9m pontos de discuss\xe3o. Outros t\xf3picos discutidos incluem: o potencial para filmes ou programas de TV auto-gerados sem valor, o papel do espa\xe7o latente e da linguagem no LLM, o impacto da tecnologia na sociedade, e as limita\xe7\xf5es das capacidades actuais de IA. Alguns utilizadores advertem contra uma interpreta\xe7\xe3o excessiva das capacidades da IA e notam que as suas limita\xe7\xf5es s\xe3o frequentemente ignoradas."]}),"\n",(0,i.jsx)(a.h2,{id:"usando-o-mmap-para-tornar-a-carga-llama-mais-r\xe1pida",children:"Usando o mmap para tornar a carga LLaMA mais r\xe1pida"}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"https://justine.lol/mmap/",children:"Original"}),".\nLLaMA utiliza mmap() para carregar modelos 100x mais rapidamente, aumenta a estabilidade da RAM e permite a execu\xe7\xe3o simult\xe2nea de m\xfaltiplos processos. Os utilizadores de Linux obt\xeam 100x de melhoria, enquanto o Windows e MacOS obt\xeam 10x. O novo carregador mmap() est\xe1 agora dispon\xedvel no GitHub sob licen\xe7a MIT. O colaborador an\xf3nimo @Slaren adicionou suporte mmap() ao LLaMA-7B, permitindo tempos de carregamento instant\xe2neos sem altera\xe7\xe3o do formato do ficheiro. O novo formato de ficheiro alinha os tensores numa fronteira de 32 bytes. O post explora potenciais melhorias na utiliza\xe7\xe3o do disco e interrup\xe7\xe3o do desempenho. Justine Tunney escreve sobre Twitter e Github em utilidades padr\xe3o, dirigido a especialistas na mat\xe9ria. \xc9 claro e conciso, sem preconceitos ou declara\xe7\xf5es pol\xedticas ou religiosas. Um utilizador da Discussion Service comenta que o post de Tunney \xe9 um grande recurso para a aprendizagem."]}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35455930",children:"Discussion Service"}),".\nA utiliza\xe7\xe3o do mmap para tornar a carga LLaMA mais r\xe1pida \xe9 o foco principal do artigo, apesar do drama em torno da atribui\xe7\xe3o e das quest\xf5es t\xe9cnicas na sec\xe7\xe3o de coment\xe1rios. Os benef\xedcios e desvantagens do mmap s\xe3o discutidos, bem como os m\xe9ritos t\xe9cnicos do LLaMA.cpp do Facebook. Os utilizadores discutem a utilidade das mudan\xe7as do LLaMA e os pr\xf3s e contras de v\xe1rias caracter\xedsticas, proporcionando valiosos conhecimentos aos leitores com conhecimentos t\xe9cnicos interessados em aprender mais sobre a IA e a implementa\xe7\xe3o de modelos. O post destaca uma abordagem de engenharia de sistemas a um problema e uma tend\xeancia envolvendo c\xf3digo propriet\xe1rio em bibliotecas, gerando discuss\xe3o sobre a utiliza\xe7\xe3o de Huge Pages e a dificuldade de resolver estrangulamentos de IO. A melhoria revolucion\xe1ria do desempenho utilizando o mmap chamou a aten\xe7\xe3o de especialistas na mat\xe9ria."]})]})}function u(e={}){const{wrapper:a}={...(0,r.R)(),...e.components};return a?(0,i.jsx)(a,{...e,children:(0,i.jsx)(m,{...e})}):m(e)}}}]);